#!/usr/bin/env python3
"""Original MIT SH-2 special priority/color diagnostic; adjacent LICENSE.

ST-058-R2 §§10.3/11.2/12.3. Guest writes both bitmaps, palette, flags,
code A/B and color controls. All graphics are computed by the devices.
"""
import argparse
import hashlib
from pathlib import Path
import struct
from build_effects import assembler, store

HERE = Path(__file__).resolve().parent


def build():
    source = '; Original MIT special priority/color guest. Generated by build_special_video.py.\n'
    for off, value in [(0x10,0x4FFF),(0x12,0xEEEE),(0x18,0x5555),(0x1A,0xEEEE),
                       (0x20, 3), (0x28, 0x3202), (0x2C, 0x30), (0x3C, 0x20),
                       (0xF8, 0x302), (0xEA, 2), (0xEE, 2), (0xEC, 1),
                       (0x108, 15), (0x24, 0), (0x26, 0x0102),
                       (0x78, 1), (0x7C, 1), (0x88, 1), (0x8C, 1)]:
        source += store(0x25F80000 + off, value)
    for y in range(2):
        source += store(0x25E00000 + y * 256, 0x12341234, 'l')
        for x in range(8):
            source += store(0x25E40000 + (y * 512 + x) * 2, 0xFC00)
    for index in [1, 2, 3, 4]:
        source += store(0x25F00000 + index * 2, 0x801F)
    source += store(0x25F80000, 0x8000)
    source += store(0x0600A300, 0x600D, 'l') + 'park:\nsleep\nbra park\nnop\n'
    code = assembler.assemble(source, base=0x200)
    assert len(code) < 0x10000
    rom = bytearray(524288)
    rom[:8] = struct.pack('>II', 0x200, 0x06100000)
    rom[0x200:0x200+len(code)] = code
    lines = ['# Original MIT special priority/color BIOS fixture. Adjacent LICENSE.',
             '# Generated from special-video.s by build_special_video.py; unspecified bytes zero.']
    for at in range(0, len(rom), 16):
        chunk = rom[at:at+16]
        if any(chunk):
            lines.append(f'{at:04X} ' + ' '.join(f'{w:04X}' for w in struct.unpack('>8H', chunk)))
    return source, '\n'.join(lines)+'\n', hashlib.sha256(rom).hexdigest()


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    source, text, digest = build()
    for path, value in [(HERE/'special-video.s', source), (HERE/'special-video.hex', text)]:
        if args.check:
            assert path.read_text() == value, f'Rebuild {path.name}'
        else:
            path.write_text(value)
    print(f'{"Verified" if args.check else "Built"} special-video.hex; expanded ROM SHA-256 {digest}')
